package com.aistock.prediction.portfolioquestion;
import com.aistock.common.BusinessException;import com.aistock.prediction.maas.MaasOperationGate;import com.fasterxml.jackson.databind.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import java.util.*;import java.time.*;import java.sql.Timestamp;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
import static com.aistock.prediction.portfolioquestion.PortfolioQuestionRecords.*;
public final class PortfolioQuestionRepository {
 private static final String KIND="PORTFOLIO_QUESTION";private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final TransactionTemplate tx;private final MaasOperationGate gate;
 public PortfolioQuestionRepository(JdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;gate=new MaasOperationGate(jdbc);tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);}
 public Receipt replay(UUID owner,Request in,Clock clock){var prior=read(in.operationId(),false);if(prior==null)return null;check(prior,owner,in);return tx.execute(s->{lockSlot(clock);var row=read(in.operationId(),true);check(row,owner,in);return expire(row,clock);});}
 public Claim claim(UUID owner,Request in,Facts facts,Clock clock){
  if(owner==null||in==null||in.operationId()==null||in.analysisId()==null||facts==null||!in.analysisId().toString().equals(facts.localContext().path("sourceAnalysisId").asText()))throw PortfolioQuestionInput.invalid();
  String context=json(facts.localContext(),262144),question=PortfolioQuestionInput.normalize(in.question());if(!question.equals(in.question()))throw PortfolioQuestionInput.invalid();
  return tx.execute(s->{owned(owner,in.analysisId());lockSlot(clock);var previous=read(in.operationId(),true);if(previous!=null){check(previous,owner,in);return new Claim(false,expire(previous,clock));}
   var cached=jdbc.queryForList("select answer_id from portfolio_question_result where owner_id=? and analysis_id=? and context_hash=?",String.class,owner.toString(),in.analysisId().toString(),facts.contextHash());String answer=cached.isEmpty()?null:cached.get(0);Instant now=clock.instant();
   if(answer==null)gate.lockAndAcquire(KIND,in.operationId(),now);
   jdbc.update("insert into portfolio_question_operation(operation_id,owner_id,analysis_id,question,request_hash,context_hash,context_json,state,answer_id,accepted_at,deadline_at,lease_until,generation,finished_at) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",in.operationId().toString(),owner.toString(),in.analysisId().toString(),question,hash(in),facts.contextHash(),context,answer==null?"RUNNING":"SUCCEEDED",answer,ts(now),ts(now.plusSeconds(45)),ts(now.plusSeconds(50)),UUID.randomUUID().toString(),answer==null?null:ts(now));return new Claim(answer==null,receipt(read(in.operationId(),true)));
  });
 }
 public Receipt complete(UUID owner,UUID op,Answer answer,String safeError,Clock clock){return tx.execute(s->{
  lockSlot(clock);var row=read(op,true);checkOwner(row,owner);var initial=expire(row,clock);if(!"RUNNING".equals(initial.state()))return initial;var slot=gate.lock(clock.instant());if(!gate.owns(slot,KIND,op))throw conflict();String generation=row.get("generation").toString(),id=null,error=safeError;
  if(error==null){if(answer==null||!Set.of("ANSWERED","OUT_OF_SCOPE").contains(answer.status())||!Set.of("PROFIT","RETURN","CONCENTRATION","COVERAGE","LIMITATION").contains(answer.topic()))throw PortfolioQuestionInput.evidence();String paragraphs=json(answer.paragraphs(),16384);id=UUID.randomUUID().toString();jdbc.update("insert into portfolio_question_result(answer_id,owner_id,analysis_id,question,context_hash,context_json,status,topic,paragraphs_json,created_at) values(?,?,?,?,?,?,?,?,?,?)",id,owner.toString(),row.get("analysis_id"),row.get("question"),row.get("context_hash"),row.get("context_json"),answer.status(),answer.topic(),paragraphs,ts(clock.instant()));}
  else if(!error.matches("[A-Z0-9_]{1,64}"))error="AI_UNAVAILABLE";
  Instant finalNow=clock.instant();int changed=jdbc.update("update portfolio_question_operation set state=?,answer_id=?,error_code=?,finished_at=? where operation_id=? and owner_id=? and generation=? and state='RUNNING' and deadline_at>? and lease_until>?",id==null?"FAILED":"SUCCEEDED",id,error,ts(finalNow),op.toString(),owner.toString(),generation,ts(finalNow),ts(finalNow));if(changed!=1)throw conflict();gate.release(KIND,op);return receipt(read(op,true));
 });}
 public Receipt operation(UUID owner,UUID op,Clock clock){checkOwner(read(op,false),owner);return tx.execute(s->{lockSlot(clock);var row=read(op,true);checkOwner(row,owner);return expire(row,clock);});}
 public JsonNode get(UUID owner,UUID answer){var found=jdbc.queryForList("select * from portfolio_question_result where owner_id=? and answer_id=?",owner.toString(),answer.toString());if(found.isEmpty())throw missing();return result(found.get(0));}
 public Page list(UUID owner,UUID analysis,String before,String upper,boolean configured,Clock clock){owned(owner,analysis);Long b=number(before),u=number(upper);if(b!=null&&(u==null||b>u))throw PortfolioQuestionInput.invalid();if(u==null)u=jdbc.queryForObject("select max(history_seq) from portfolio_question_result where owner_id=? and analysis_id=?",Long.class,owner.toString(),analysis.toString());var items=new ArrayList<JsonNode>();String next=null;if(u!=null){var rows=b==null?jdbc.queryForList("select * from portfolio_question_result where owner_id=? and analysis_id=? and history_seq<=? order by history_seq desc limit 11",owner.toString(),analysis.toString(),u):jdbc.queryForList("select * from portfolio_question_result where owner_id=? and analysis_id=? and history_seq<=? and history_seq<? order by history_seq desc limit 11",owner.toString(),analysis.toString(),u,b);for(var row:rows.subList(0,Math.min(10,rows.size())))items.add(result(row));if(rows.size()>10)next=rows.get(9).get("history_seq").toString();}
  var latest=jdbc.queryForList("select operation_id from portfolio_question_operation where owner_id=? and analysis_id=? order by history_seq desc limit 1",String.class,owner.toString(),analysis.toString());var attempt=latest.isEmpty()?null:operation(owner,UUID.fromString(latest.get(0)),clock);return new Page(List.copyOf(items),u==null?null:u.toString(),next,attempt,configured);
 }
 private void lockSlot(Clock clock){gate.lock(clock.instant());gate.lock(clock.instant());}
 private Receipt expire(Map<String,Object> row,Clock clock){if("RUNNING".equals(row.get("state"))){Instant now=clock.instant();if(!now.isBefore(instant(row.get("deadline_at")))||!now.isBefore(instant(row.get("lease_until")))){jdbc.update("update portfolio_question_operation set state='FAILED',error_code='AI_INTERRUPTED',finished_at=? where operation_id=? and state='RUNNING'",ts(now),row.get("operation_id"));gate.release(KIND,UUID.fromString(row.get("operation_id").toString()));row=read(UUID.fromString(row.get("operation_id").toString()),true);}}return receipt(row);}
 private void owned(UUID owner,UUID analysis){if(jdbc.queryForObject("select count(*) from portfolio_analysis_result where owner_id=? and analysis_id=?",Integer.class,owner.toString(),analysis.toString())!=1)throw missing();}
 private Map<String,Object> read(UUID op,boolean lock){var rows=jdbc.queryForList("select * from portfolio_question_operation where operation_id=?"+(lock?" for update":""),op.toString());return rows.isEmpty()?null:rows.get(0);}
 private void checkOwner(Map<String,Object> row,UUID owner){if(row==null||!owner.toString().equals(row.get("owner_id")))throw missing();}
 private void check(Map<String,Object> row,UUID owner,Request in){checkOwner(row,owner);if(!hash(in).equals(row.get("request_hash")))throw conflict();}
 private Receipt receipt(Map<String,Object> row){return new Receipt(UUID.fromString(row.get("operation_id").toString()),UUID.fromString(row.get("analysis_id").toString()),row.get("question").toString(),row.get("state").toString(),row.get("answer_id")==null?null:UUID.fromString(row.get("answer_id").toString()),(String)row.get("error_code"),instant(row.get("deadline_at")));}
 private JsonNode result(Map<String,Object> row){var n=mapper.createObjectNode();for(var pair:List.of(new String[]{"answer_id","answerId"},new String[]{"analysis_id","analysisId"},new String[]{"question","question"},new String[]{"context_hash","contextHash"},new String[]{"status","status"},new String[]{"topic","topic"}))n.put(pair[1],row.get(pair[0]).toString());n.put("createdAt",instant(row.get("created_at")).toString());try{n.set("context",mapper.readTree(row.get("context_json").toString()));n.set("paragraphs",mapper.readTree(row.get("paragraphs_json").toString()));}catch(Exception e){throw PortfolioQuestionInput.evidence();}return n;}
 private String hash(Request in){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(List.of(in.analysisId().toString(),PortfolioQuestionInput.normalize(in.question()),in.disclosureAccepted()))));}catch(Exception e){throw PortfolioQuestionInput.invalid();}}
 private String json(Object obj,int max){try{byte[] raw=mapper.writeValueAsBytes(obj);if(raw.length>max)throw PortfolioQuestionInput.budget();return new String(raw,StandardCharsets.UTF_8);}catch(BusinessException e){throw e;}catch(Exception e){throw PortfolioQuestionInput.evidence();}}
 private Long number(String value){if(value==null)return null;try{if(!value.matches("[1-9][0-9]{0,18}"))throw PortfolioQuestionInput.invalid();return Long.valueOf(value);}catch(NumberFormatException e){throw PortfolioQuestionInput.invalid();}}
 private static Timestamp ts(Instant time){return Timestamp.from(time.truncatedTo(java.time.temporal.ChronoUnit.MILLIS));}
 private static Instant instant(Object obj){return obj instanceof Timestamp t?t.toInstant():((LocalDateTime)obj).toInstant(ZoneOffset.UTC);}
 private static BusinessException missing(){return new BusinessException("RESOURCE_NOT_FOUND","未找到本人持仓问答记录",HttpStatus.NOT_FOUND);}
 private static BusinessException conflict(){return new BusinessException("AI_REQUEST_CONFLICT","请求编号、问题或估值记录不一致，请核对原请求",HttpStatus.CONFLICT);}
}
